// Where the parts of gadgets are: rows, scroll bars, tabs, toolbar buttons and menus. Drawing a gadget and using it with
// the mouse both go by what is in here, so that what is shown is what is hit.

#include "gui_internal.hpp"

extern "C" {
int32_t bb_gui_font_size(int32_t font);
}

namespace bb::gui {
	ui_state ui;

	constexpr int default_font_size = 12;
	constexpr int menu_font_size    = 12;

	int font_size(gadget const& g)
	{
		int size = g.font ? bb_gui_font_size(g.font) : 0;
		return size > 0 ? size : default_font_size;
	}

	int row_height(gadget const& g)
	{
		return font_size(g) + 6;
	}

	int text_width(gadget const& g, const char* text, int length)
	{
		if (length < 0) {
			length = text ? int(strlen(text)) : 0;
		}
		return length * font_size(g);
	}

	int text_height(gadget const& g)
	{
		return font_size(g);
	}

	int tab_client_rect(gadget const& g, int* x, int* y, int* w, int* h)
	{
		*x = 2;
		*y = tab_height;
		*w = g.w - 4;
		*h = g.h - tab_height - 2;
		return 1;
	}

	////////////////////////////////////////////////////////////////////////////
	// Rows and scroll bars
	////////////////////////////////////////////////////////////////////////////
	int visible_rows(gadget const& g)
	{
		int rows = (g.h - 4) / row_height(g);
		return rows < 1 ? 1 : rows;
	}

	int total_rows(gadget const& g)
	{
		switch (g.kind) {
		case K_LISTBOX:
			return int(g.items.size);
		case K_TREEVIEW:
			return count_visible_nodes(g);
		case K_TEXTAREA: {
			buffer<visual_line> lines;
			build_lines(g, lines);
			int count = int(lines.size);
			lines.release();
			return count;
		}
		default:
			return 0;
		}
	}

	// Whether the scroll bar is there: text areas always have one.
	static bool has_bar(gadget const& g)
	{
		if (g.kind == K_TEXTAREA) {
			return true;
		}
		if ((g.kind == K_LISTBOX) || (g.kind == K_TREEVIEW)) {
			return total_rows(g) > visible_rows(g);
		}
		return false;
	}

	void content_rect(gadget const& g, int* x, int* y, int* w, int* h)
	{
		*x = *y = 0;
		*w      = g.w;
		*h      = g.h;
		switch (g.kind) {
		case K_LISTBOX:
		case K_TREEVIEW:
		case K_TEXTAREA:
			*x = *y = 2;
			*w      = g.w - 4 - (has_bar(g) ? bar_width : 0);
			*h      = g.h - 4;
			break;
		case K_TEXTFIELD:
			*x = 3;
			*y = 2;
			*w = g.w - 6;
			*h = g.h - 4;
			break;
		default:
			break;
		}
		if (*w < 0) {
			*w = 0;
		}
		if (*h < 0) {
			*h = 0;
		}
	}

	void scroll_rect(gadget const& g, int* x, int* y, int* w, int* h)
	{
		*x = g.w - 2 - bar_width;
		*y = 2;
		*w = bar_width;
		*h = g.h - 4;
	}

	// Where the thumb of a scroll bar is, from the arrow at the start: its distance and size.
	void scroll_thumb(int position, int visible, int total, int length, int* start, int* size)
	{
		int track = length - 2 * bar_width;
		if (track < 1) {
			track = 1;
		}
		if (visible < 1) {
			visible = 1;
		}
		if (total < visible) {
			total = visible;
		}
		int thumb = int(int64_t(track) * visible / total);
		if (thumb < 12) {
			thumb = track < 12 ? track : 12;
		}
		int range = total - visible;
		int at    = range > 0 ? int(int64_t(track - thumb) * position / range) : 0;
		*start    = bar_width + at;
		*size     = thumb;
	}

	void build_lines(gadget const& g, buffer<visual_line>& out)
	{
		int  size = font_size(g);
		int  cols = (g.w - 4 - bar_width) / size;
		bool wrap = (g.style & 1) != 0;
		if (cols < 1) {
			cols = 1;
		}
		const char* text = g.text ? g.text : "";
		int         n    = int(strlen(text));
		int         at   = 0;
		for (;;) {
			int end = at;
			while ((end < n) && (text[end] != '\r')) {
				end++;
			}
			if (!wrap) {
				visual_line line;
				line.start  = at;
				line.length = end - at;
				out.push(line);
			} else {
				int begin = at;
				do {
					int stop = begin + cols;
					if (stop >= end) {
						stop = end;
					} else {
						// A word that doesn't fit goes to the next line, unless it is longer than a line.
						int cut = stop;
						while ((cut > begin) && (text[cut] != ' ')) {
							cut--;
						}
						if (cut > begin) {
							stop = cut + 1;
						}
					}
					visual_line line;
					line.start  = begin;
					line.length = stop - begin;
					out.push(line);
					begin = stop;
				} while (begin < end);
			}
			if (end >= n) {
				break;
			}
			at = end + 1;
		}
	}

	static void add_rows(gadget const& g, int node_handle, int depth, buffer<tree_row>& out)
	{
		node* n = node_of(node_handle);
		if (!n) {
			return;
		}
		for (uint32_t i = 0; i < n->kids.size; i++) {
			tree_row row;
			row.node  = n->kids[i];
			row.depth = depth;
			out.push(row);
			node* kid = node_of(n->kids[i]);
			if (kid && kid->expanded) {
				add_rows(g, n->kids[i], depth + 1, out);
			}
		}
	}

	void build_tree_rows(gadget const& g, buffer<tree_row>& out)
	{
		add_rows(g, g.root, 0, out);
	}

	void clamp_scroll(gadget& g)
	{
		int most = total_rows(g) - visible_rows(g);
		if (most < 0) {
			most = 0;
		}
		g.scroll_y = g.scroll_y > most ? most : (g.scroll_y < 0 ? 0 : g.scroll_y);
		g.scroll   = g.scroll > most ? most : (g.scroll < 0 ? 0 : g.scroll);
		// A list that has a selected row shows it, when what is selected is changed by the program.
		if ((g.kind == K_LISTBOX) && (g.selected >= 0)) {
			if (g.selected < g.scroll) {
				g.scroll = g.selected;
			} else if (g.selected >= g.scroll + visible_rows(g)) {
				g.scroll = g.selected - visible_rows(g) + 1;
			}
		}
	}

	// The cursor of a text field or text area is in what is seen.
	void caret_to_view(gadget& g)
	{
		if (g.kind == K_TEXTFIELD) {
			int x = g.caret * font_size(g), width = g.w - 6;
			if (x - g.scroll_x > width) {
				g.scroll_x = x - width;
			}
			if (x < g.scroll_x) {
				g.scroll_x = x;
			}
		} else if (g.kind == K_TEXTAREA) {
			buffer<visual_line> lines;
			build_lines(g, lines);
			int row = 0;
			for (uint32_t i = 0; i < lines.size; i++) {
				if ((g.caret >= lines[i].start) && (g.caret <= lines[i].start + lines[i].length)) {
					row = int(i);
					// The end of a wrapped line is the start of the next one.
					if ((g.caret < lines[i].start + lines[i].length) || (i + 1 == lines.size) || !(g.style & 1)
					    || (g.text[g.caret] == '\r')) {
						break;
					}
				}
			}
			int visible = visible_rows(g);
			if (row < g.scroll_y) {
				g.scroll_y = row;
			} else if (row >= g.scroll_y + visible) {
				g.scroll_y = row - visible + 1;
			}
			if (!(g.style & 1) && (row < int(lines.size))) {
				int x = (g.caret - lines[uint32_t(row)].start) * font_size(g), width = g.w - 4 - bar_width;
				if (x - g.scroll_x > width) {
					g.scroll_x = x - width;
				}
				if (x < g.scroll_x) {
					g.scroll_x = x;
				}
			}
			lines.release();
			clamp_scroll(g);
		}
		dirty();
	}

	////////////////////////////////////////////////////////////////////////////
	// Tabs and toolbars
	////////////////////////////////////////////////////////////////////////////
	void tab_rect(gadget const& g, int index, int* x, int* y, int* w, int* h)
	{
		int at = 2;
		for (int i = 0; i <= index && i < int(g.items.size); i++) {
			int width = text_width(g, g.items[uint32_t(i)].text, -1) + 20 + (strip_of(g.strip) && (g.items[uint32_t(i)].icon >= 0) ? strip_of(g.strip)->size + 4 : 0);
			if (i == index) {
				*x = at;
				*w = width;
			}
			at += width;
		}
		*y = 0;
		*h = tab_height;
	}

	void tool_button_rect(gadget const& g, int icon, int* x, int* y, int* w, int* h)
	{
		icon_strip* strip = strip_of(g.strip);
		int         size  = strip ? strip->size : 16;
		int         at    = 2;
		for (int i = 0; i < icon && i < int(g.tool_blank.size); i++) {
			at += g.tool_blank[uint32_t(i)] ? 8 : size + 8;
		}
		*x = at;
		*w = size + 8;
		*h = size + 8;
		*y = (g.h - *h) / 2;
		if (*y < 0) {
			*y = 0;
		}
	}

	int tool_button_index(gadget const& g, int icon)
	{
		if ((icon < 0) || (icon >= int(g.tool_blank.size)) || g.tool_blank[uint32_t(icon)]) {
			return -1;
		}
		int index = 0;
		for (int i = 0; i < icon; i++) {
			if (!g.tool_blank[uint32_t(i)]) {
				index++;
			}
		}
		return index;
	}

	////////////////////////////////////////////////////////////////////////////
	// Windows and menus
	////////////////////////////////////////////////////////////////////////////
	int menu_row_height()
	{
		return menu_font_size + 8;
	}

	static int menu_text_width(const char* text)
	{
		int n = 0;
		for (const char* p = text; p && *p; p++) {
			if (*p != '&') {
				n++;
			}
		}
		return n * menu_font_size;
	}

	void menu_bar_rect(int window, int index, int* x, int* y, int* w, int* h)
	{
		gadget* g = gadget_of(window);
		menu*   root = g ? menu_of(g->menu) : nullptr;
		int     l, t, r, b;
		if (g) {
			window_decoration(*g, &l, &t, &r, &b);
		} else {
			l = t = 0;
		}
		int at = l;
		*x = at;
		*w = 0;
		for (int i = 0; root && (i <= index) && (i < int(root->kids.size)); i++) {
			menu* m = menu_of(root->kids[uint32_t(i)]);
			int   width = menu_text_width(m ? m->text : "") + 16;
			if (i == index) {
				*x = at;
				*w = width;
			}
			at += width;
		}
		int frame = g ? ((g->style & 1) ? ((g->style & 2) ? frame_width : 3) : 1) : 0;
		*y        = frame + ((g && (g->style & 1)) ? title_bar_height(*g) : 0);
		*h        = menu_height;
	}

	void menu_popup_rect(int window, int level, int* x, int* y, int* w, int* h)
	{
		*x = *y = *w = *h = 0;
		if ((ui.menu_window != window) || (level < 0) || (level >= int(ui.menu_path.size))) {
			return;
		}
		gadget* g = gadget_of(window);
		menu*   m = menu_of(ui.menu_path[uint32_t(level)]);
		if (!g || !m) {
			return;
		}
		int rows = int(m->kids.size), width = 0;
		for (int i = 0; i < rows; i++) {
			menu* kid = menu_of(m->kids[uint32_t(i)]);
			int   tw  = menu_text_width(kid ? kid->text : "") + (kid && kid->kids.size ? 16 : 0);
			width     = tw > width ? tw : width;
		}
		*w = width + 44;
		*h = rows * menu_row_height() + 4;
		if (level == 0) {
			menu* root = menu_of(g->menu);
			int   index = 0;
			for (uint32_t i = 0; root && (i < root->kids.size); i++) {
				if (root->kids[i] == ui.menu_path[0]) {
					index = int(i);
				}
			}
			int bx, by, bw, bh;
			menu_bar_rect(window, index, &bx, &by, &bw, &bh);
			*x = bx;
			*y = by + bh;
		} else {
			int px, py, pw, ph;
			menu_popup_rect(window, level - 1, &px, &py, &pw, &ph);
			menu* parent = menu_of(ui.menu_path[uint32_t(level - 1)]);
			int   index  = 0;
			for (uint32_t i = 0; parent && (i < parent->kids.size); i++) {
				if (parent->kids[i] == ui.menu_path[uint32_t(level)]) {
					index = int(i);
				}
			}
			*x = px + pw - 2;
			*y = py + 2 + index * menu_row_height() - 2;
		}
	}

	// The boxes in the title of a window, and the height of that. Says how many there are.
	int window_buttons(gadget const& g, int* close_x, int* max_x, int* min_x, int* y)
	{
		if (!(g.style & 1)) {
			return 0;
		}
		int frame = (g.style & 2) ? frame_width : 3;
		int bw    = title_box_width(g);
		*y        = frame + (title_bar_height(g) - title_box_height(g)) / 2;
		*close_x  = g.w - frame - 2 - bw;
		*max_x    = *close_x - bw;
		*min_x    = *max_x - bw;
		// Tool windows can be sized, but have no boxes for maximizing and minimizing.
		return ((g.style & 2) && !(g.style & 16)) ? 3 : 1;
	}

	// Windows that are minimized are bars at the bottom of the desktop, next to each other.
	void minimized_rect(int window, int* x, int* y, int* w, int* h)
	{
		gadget* desk = gadget_of(desktop_handle());
		int     slot = 0;
		for (uint32_t i = 0; desk && (i < desk->kids.size); i++) {
			gadget* k = gadget_of(desk->kids[i]);
			if (desk->kids[i] == window) {
				break;
			}
			if (k && k->visible && k->minimized) {
				slot++;
			}
		}
		*w = 160;
		*h = title_height;
		*x = slot * 164 + 2;
		*y = (desk ? desk->ch : 0) - title_height - 2;
	}
} // namespace bb::gui
